/*
 * stack.h -- CS 313 P1: a growable int stack.
 *
 * DO NOT EDIT THIS FILE. The autograder uses its own copy.
 *
 * The stack stores ints in a heap array `data` of length `capacity`.
 * The top of the stack is data[size - 1].
 *
 * Growth rule: a new stack has capacity 1. When stack_push is called and
 * size == capacity, the stack grows:
 *   1. malloc a NEW array of 2 * capacity ints,
 *   2. copy all `size` elements into it with a loop you write,
 *   3. free the old array,
 *   4. double capacity,
 *   5. add the old capacity to `copies`.
 * Then the new element is written. Do not use realloc.
 *
 * Empty-stack contract: stack_pop and stack_peek on an empty stack return
 * false and do not touch *out. They never print, exit, or crash.
 */
#ifndef STACK_H
#define STACK_H

#include <stdbool.h>

typedef struct {
    int *data;      /* heap array holding the elements             */
    int size;       /* number of elements currently on the stack   */
    int capacity;   /* length of the data array                    */
    long copies;    /* total element copies made by all growths    */
} Stack;

/* Return a new empty stack with capacity 1 and copies 0.
 * Return NULL if memory allocation fails. */
Stack *stack_create(void);

/* Free the data array and the Stack itself. Does nothing if s is NULL. */
void stack_destroy(Stack *s);

/* Push x on top. Grow first if the stack is full.
 * Return true on success, false if memory allocation fails. */
bool stack_push(Stack *s, int x);

/* If the stack is empty, return false and leave *out unchanged.
 * Otherwise remove the top element, store it in *out, and return true. */
bool stack_pop(Stack *s, int *out);

/* Like stack_pop, but does not remove the element. */
bool stack_peek(const Stack *s, int *out);

/* Number of elements on the stack. */
int stack_size(const Stack *s);

/* true if the stack has no elements. */
bool stack_is_empty(const Stack *s);

/* Total element copies made by all growths so far. */
long stack_copies(const Stack *s);

#endif
